// Flatten and extract all `voiceText` values from items
const voice_texts = items.flatMap(item =>
  item.json.output
    .map(p => p.voiceText)
    .filter(Boolean) // Remove undefined/null
);

// Return up to 7 voiceText fields
return [
  {
    json: {
      voice_text1: voice_texts[0] || null,
      voice_text2: voice_texts[1] || null,
      voice_text3: voice_texts[2] || null,
      voice_text4: voice_texts[3] || null,
      voice_text5: voice_texts[4] || null,
      voice_text6: voice_texts[5] || null,
      voice_text7: voice_texts[6] || null,
    }
  }
];

// Collect voice_text1 through voice_text7 from input
const input = items[0].json;

const parts = [
  input.voice_text1,
  input.voice_text2,
  input.voice_text3,
  input.voice_text4,
  input.voice_text5,
  input.voice_text6,
  input.voice_text7
]

// Join with double line breaks (ElevenLabs-friendly section separation)
const combinedVoiceover = parts.join('\n\n');

return [
  {
    json: {
      voiceover_script: combinedVoiceover
    }
  }
];

function appendFilenameToUrl(directUrl, filename) {
  return `${directUrl}&fileName=${encodeURIComponent(filename)}`;
}

// Step 1: Get direct download link
const VoiceoverUrl = $input.first().json.webContentLink;
const filename = $input.first().json.name;

// Step 2: Combine link + filename
const directVoiceoverUrl = appendFilenameToUrl(VoiceoverUrl, filename);

// Step 3: Return result
return [{
  directVoiceoverUrl,
}];

// Get the row data
const row = items[0].json;

// Collect all music links
const musicLinks = [
  row.music1,
  row.music2,
  row.music3,
  row.music4,
  row.music5,
  row.music6,
  row.music7,
  row.music8
].filter(link => !!link); // Remove null/undefined/empty strings

// Randomly select one
const selectedMusic = musicLinks[Math.floor(Math.random() * musicLinks.length)] || null;

return [
  {
    json: {
      music: selectedMusic
    }
  }
];

// Get the nested array of prompts from the single item
const prompts = items[0].json.output;

// Extract image_prompt values
const image_prompts = prompts.map(p => p.image_prompt);

// Return up to 7 prompts as individual fields
return [
  {
    json: {
      image_prompt1: image_prompts[0] || null,
      image_prompt2: image_prompts[1] || null,
      image_prompt3: image_prompts[2] || null,
      image_prompt4: image_prompts[3] || null,
      image_prompt5: image_prompts[4] || null,
      image_prompt6: image_prompts[5] || null,
      image_prompt7: image_prompts[6] || null,
    }
  }
];

const counter = $node["READ COUNTER"].json.counter;

const key = `image_prompt${counter}`;

// Grab prompt based on counter from EXTRACT IMAGE PROMPTS
const prompt = $node["EXTRACT IMG PROMPTS"].json[key];

if (!prompt) {
  throw new Error(`Prompt not found for key: ${key}`);
}

return [
  {
    json: {
      image_prompt: prompt
    }
  }
];

const input = $input.item.json.data.yourselection || "Image 1";

// Extract the number from the string, e.g. "Image 3" => 3
const match = input.match(/\d+/);
const selection = match ? parseInt(match[0]) : 1;

return [
  {
    json: {
      selection
    }
  }
];

// Grab the selection from Code1
const selection = $node["GET RESPONSE"].json["selection"];  // 1-4

// Grab the row from Google Sheets1
const row = $node["WRT TMP IMG LINKS"].json;

// Safety check
if (!selection || !row) {
  throw new Error("Missing selection or row data.");
}

// Column names (1–4)
const columns = [
  "tmp_image1",
  "tmp_image2",
  "tmp_image3",
  "tmp_image4"
];

// Lookup the selected image
const selectedImage1 = row[columns[selection - 1]];

return [
  {
    json: {
      selectedImage1
    }
  }
];

// 'items' contains the array of rows from the previous node (GET ALL IMAGE LINKS)
const links = items.map(item => item.json.link);

// Return each link as its own variable
return [
  {
    json: {
      link1: links[0] || null,
      link2: links[1] || null,
      link3: links[2] || null,
      link4: links[3] || null,
      link5: links[4] || null,
      link6: links[5] || null,
      link7: links[6] || null,
    }
  }
];

return items.map(item => {
  const data = item.json;

  return {
    image1: data.link1,
    image2: data.link2,
    image3: data.link3,
    image4: data.link4,
    image5: data.link5,
    image6: data.link6,
    image7: data.link7,
    music: data.music,
    voiceover: data.directVoiceoverUrl
  };
});
